using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;using System.Diagnostics;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using KianaPet;
class SkinVisualTests {
 static int checks;static List<string> names=new List<string>();static List<object> samples=new List<object>();
 static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;names.Add(name);}
 static object F(object o,string key){return o.GetType().GetField(key,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
 static void Set(object o,string key,object value){o.GetType().GetField(key,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(o,value);}
 static object Call(object o,string key,params object[] args){return o.GetType().GetMethod(key,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,args);}
 static bool Running(PetWindow pet){return (bool)F(pet,"skinVisualRunning");}
 static string Other(PetWindow pet){return SkinShuffleRules.Defaults.First(id=>id!=pet.Settings.Skin);}
 static long Alpha(BitmapSource source){var image=new FormatConvertedBitmap(source,PixelFormats.Bgra32,null,0);byte[] pixels=new byte[image.PixelWidth*image.PixelHeight*4];image.CopyPixels(pixels,image.PixelWidth*4,0);long sum=0;for(int i=3;i<pixels.Length;i+=4)sum+=pixels[i];return sum;}
 static void Frame(PetWindow pet,int index){var source=(BitmapSource)Call(pet,"CaptureSkinVisual");if(source==null)return;var visual=new DrawingVisual();using(var dc=visual.RenderOpen()){dc.DrawRectangle(new SolidColorBrush(Color.FromRgb(248,246,252)),null,new Rect(0,0,320,320));double width=source.Width*1.25,height=source.Height*1.25;dc.DrawImage(source,new Rect((320-width)/2,(320-height)/2,width,height));}var bitmap=new RenderTargetBitmap(320,320,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(Store.Root,"frame-"+index.ToString("000")+".png")))encoder.Save(file);}
 [STAThread]static int Main(string[] args){Store.Root=args[0];Store.Save(new Config{LinkChatGPT=false,MusicEnabled=false,Walking=false,Gravity=false,AmbientActions=false,SleepSchedule=false,IdleSleep=false,HideFullscreen=false,LaunchChatGPTOnStart=false,LaunchMusicOnStart=false,NoticeSound=false,SkinShuffleEnabled=false,SkinShuffleOnStart=false,SkinShuffleActions=new string[0],SmoothTransitions=true,ReduceMotion=false});var app=new Application{ShutdownMode=ShutdownMode.OnLastWindowClose};var pet=new PetWindow(true);bool passed=false,animated=false;
  pet.Loaded+=async delegate{try{
   await Task.Delay(1100);((DispatcherTimer)F(pet,"animation")).Stop();foreach(var window in app.Windows.OfType<SettingsWindow>().ToArray())window.Close();pet.IsHitTestVisible=false;Set(pet,"hover",false);Set(pet,"interaction",null);Set(pet,"menuLayerYielding",false);Set(pet,"displayPending",false);double now=((Stopwatch)F(pet,"clock")).Elapsed.TotalSeconds;Set(pet,"state","music-quiet");Set(pet,"stateAt",now-20);Set(pet,"drawnMusicState","music-quiet");pet.Settings.MusicEnabled=true;pet.Music.Current=new MusicState{Connected=true,Playing=true,Title="Synthetic music",Id="123",HasPosition=false};Call(pet,"ChooseMusicReaction",now-10,true);Call(pet,"ChooseMusicReaction",now,true);Call(pet,"DrawAnimation",20000d);pet.UpdateLayout();var old=(BitmapSource)Call(pet,"CaptureSkinVisual");animated=MotionSettings.Enabled;
   Check(!animated||old!=null&&old.IsFrozen&&Alpha(old)>10000,"frozen outgoing snapshot contains the aligned character");if(animated){var image=(Image)F(pet,"sprite");var visual=new DrawingVisual();using(var dc=visual.RenderOpen())dc.DrawImage(image.Source,new Rect(0,0,image.ActualWidth,image.ActualHeight));var reference=new RenderTargetBitmap(old.PixelWidth,old.PixelHeight,old.DpiX,old.DpiY,PixelFormats.Pbgra32);reference.Render(visual);double coverage=Alpha(old)/(double)Alpha(reference);Check(coverage>.97&&coverage<1.03,"snapshot includes the full body without inheriting its grid-row offset");}var live=(Grid)F(pet,"skinLiveVisual");var ghost=(Image)F(pet,"skinOldVisual");Check(!ghost.IsHitTestVisible,"outgoing visual never captures pointer input");double width=pet.Width,height=pet.Height,phase=(double)F(pet,"stateAt");var poll=((DispatcherTimer)F(pet,"poll")).Interval;var musicPoll=((DispatcherTimer)F(pet,"musicTimer")).Interval;var session=F(pet,"musicReactionPlanner");var entered=F(session,"enteredAt");string target=Other(pet);Frame(pet,0);Check((bool)Call(pet,"ApplyAutomaticSkin",target,now),"automatic skin applies through the existing safe handoff");
   if(animated){Check(Running(pet)&&live.Opacity==0&&ghost.Source!=null&&ghost.Visibility==Visibility.Visible,"transition begins with the old silhouette and hidden new live sprite");Check(Alpha((BitmapSource)ghost.Source)==Alpha(old),"outgoing snapshot retains old position and alpha");bool oldPartial=false,newPartial=false;var clock=Stopwatch.StartNew();int index=1;while(clock.ElapsedMilliseconds<430){await Task.Delay(15);double oldOpacity=ghost.Visibility==Visibility.Visible?ghost.Opacity:0,newOpacity=live.Opacity;if(oldOpacity>.02&&oldOpacity<.95&&newOpacity<.01)oldPartial=true;if(newOpacity>.02&&newOpacity<.98)newPartial=true;samples.Add(new{milliseconds=clock.ElapsedMilliseconds,oldOpacity,newOpacity});Frame(pet,index++);}Check(oldPartial&&newPartial,"real WPF frames include outgoing and incoming fade stages");Check(!Running(pet)&&live.Opacity==1&&ghost.Source==null&&ghost.Visibility==Visibility.Hidden,"completion restores opacity and releases snapshot");}
   else Check(!Running(pet)&&live.Opacity==1,"system-disabled animations use immediate handoff");
   Check(pet.CurrentAction=="music-quiet"&&(double)F(pet,"stateAt")==phase&&Equals(F(session,"enteredAt"),entered)&&ReferenceEquals(session,F(pet,"musicReactionPlanner")),"visual transition preserves current music action and timeline");Check(poll==((DispatcherTimer)F(pet,"poll")).Interval&&musicPoll==((DispatcherTimer)F(pet,"musicTimer")).Interval&&pet.Width==width&&pet.Height==height&&F(pet,"interaction")==null,"visual effect preserves polling, bounds and silent automatic behavior");
   if(animated){Set(pet,"state","idle");Call(pet,"ApplyAutomaticSkin",Other(pet),now);await Task.Delay(40);int token=(int)F(pet,"skinVisualToken");string latest=Other(pet);Call(pet,"ApplyAutomaticSkin",latest,now);Check(Running(pet)&&(int)F(pet,"skinVisualToken")>token,"rapid replacement owns a new transition generation");await Task.Delay(150);Check(Running(pet),"older completion cannot stop a newer transition");await Task.Delay(240);Check(pet.Settings.Skin==latest&&!Running(pet)&&live.Opacity==1&&ghost.Source==null,"rapid selection ends on latest outfit without a stale overlay");
    pet.SelectSkin(Other(pet));Check(Running(pet)&&F(pet,"interaction")==null,"manual selection preserves its underlying action and adds the visual transition");Call(pet,"SkinVisualActionChanged","idle");Check(Running(pet),"preserved manual action does not cancel its own transition");await Task.Delay(350);Check(!Running(pet)&&live.Opacity==1,"manual transition finishes normally");Set(pet,"interaction",null);
    Call(pet,"ApplyAutomaticSkin",Other(pet),now);Call(pet,"SkinVisualActionChanged","running");Check(!Running(pet)&&live.Opacity==1&&ghost.Source==null,"new priority action immediately reveals the live character");
    Call(pet,"ApplyAutomaticSkin",Other(pet),now);pet.Settings.LinkChatGPT=true;pet.Link.Current.Connected=true;pet.Link.Current.State="running";pet.Link.Current.At=DateTime.UtcNow;Call(pet,"MaintainSkinVisual");Check(!Running(pet)&&live.Opacity==1,"incoming GPT work cancels only the cosmetic fade");pet.Settings.LinkChatGPT=false;pet.Link.Current.Connected=false;
    Call(pet,"ApplyAutomaticSkin",Other(pet),now);Set(pet,"pressed",true);Call(pet,"MaintainSkinVisual");Check(!Running(pet)&&live.Opacity==1,"pointer interaction does not operate an invisible live sprite");Set(pet,"pressed",false);
    Call(pet,"ApplyAutomaticSkin",Other(pet),now);pet.Hide();Check(!Running(pet)&&ghost.Source==null,"hiding releases the old snapshot");pet.Show();Check(live.Opacity==1,"showing again cannot leave the body transparent");
    Call(pet,"ApplyAutomaticSkin",Other(pet),now);pet.ResizePet();Check(!Running(pet)&&ghost.Source==null,"resize cancels the old-size snapshot");
    Call(pet,"ApplyAutomaticSkin",Other(pet),now);pet.Settings.ReduceMotion=true;Call(pet,"ApplyInputOptions");Check(!Running(pet)&&live.Opacity==1&&ghost.Source==null,"enabling reduced motion interrupts and cleans up an active fade");
   }
   pet.Settings.ReduceMotion=true;Call(pet,"ApplyInputOptions");Call(pet,"ApplyAutomaticSkin",Other(pet),now);Check(!Running(pet)&&live.Opacity==1&&ghost.Source==null,"reduced motion performs a direct safe swap");pet.Settings.ReduceMotion=false;pet.Settings.SmoothTransitions=false;Call(pet,"ApplyInputOptions");Call(pet,"ApplyAutomaticSkin",Other(pet),now);Check(!Running(pet)&&live.Opacity==1&&ghost.Source==null,"disabled smooth transitions perform a direct swap");pet.Settings.SmoothTransitions=true;Call(pet,"ApplyInputOptions");Call(pet,"ApplyAutomaticSkin",Other(pet),now);passed=true;
  }catch(Exception e){Store.Atomic("error.json",new{error=e.ToString(),checks});}finally{foreach(var window in app.Windows.Cast<Window>().Where(window=>window!=pet).ToArray())window.Close();pet.Close();}};app.Run(pet);
  try{Check(!Running(pet)&&((Grid)F(pet,"skinLiveVisual")).Opacity==1&&((Image)F(pet,"skinOldVisual")).Source==null,"closing mid-transition clears animations and bitmap references");}catch(Exception e){passed=false;Store.Atomic("error.json",new{error=e.ToString(),checks});}Store.Atomic("result.json",new{passed,animated,checks,names,samples});return passed?0:1;
 }
}
